def _schema_violations(self, effective: Dict[str, Any]) -> List[str]:
    """List the ways an effective policy violates the loaded schema."""
    validators = {
        "bool": lambda v: isinstance(v, bool),
        "int": lambda v: isinstance(v, int) and not isinstance(v, bool),
        "float": lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
        "string": lambda v: isinstance(v, str),
        "enum": lambda v: isinstance(v, str),
    }
    violations: List[str] = []
    for dp, val in sorted(_flatten_dict(effective).items()):
        defn = self._schema.get(dp)
        if defn is None:
            violations.append(f"unknown parameter '{dp}'")
            continue
        validator = validators.get(defn.type)
        if validator and not validator(val):
            violations.append(f"{dp} = {val!r} (expected {defn.type})")
        if defn.allowed_values and val not in defn.allowed_values:
            violations.append(
                f"{dp} = {val!r} not in allowed_values {defn.allowed_values}"
            )
    return violations

